+//! Temporary sampled attribution only; never compiled into production artifacts.
+use std::cell::RefCell;
+use std::time::Instant;
+const N: usize = 16;
+struct State { active: bool, enabled: bool, index: usize, nanos: [u64;N], hits: [u64;N] }
+thread_local! { static STATE: RefCell<State> = RefCell::new(State { active:false, enabled:false, index:0, nanos:[0;N], hits:[0;N] }); }
+pub fn reset() { STATE.with(|s| *s.borrow_mut() = State { active:false, enabled:true, index:0, nanos:[0;N], hits:[0;N] }); }
+pub fn disable() { STATE.with(|s| {s.borrow_mut().enabled=false; s.borrow_mut().active=false;}); }
+pub struct Guard { index: usize, start: Option<Instant> }
+pub fn phase(index:usize) -> Guard {
+    let active = STATE.with(|s| { let s=s.borrow(); s.active && s.enabled });
+    Guard { index, start: active.then(Instant::now) }
+}
+impl Drop for Guard {
+    fn drop(&mut self) { if let Some(start)=self.start { let ns=start.elapsed().as_nanos() as u64; STATE.with(|s| {let mut s=s.borrow_mut(); s.nanos[self.index]+=ns; s.hits[self.index]+=1;}); } }
+}
+pub struct Observer;
+impl crate::output::RunObserver for Observer {
+    fn observe<T>(&self, phase:crate::output::RunPhase, work:impl FnOnce()->T)->T {
+        use crate::output::RunPhase;
+        if phase==RunPhase::Kernel { STATE.with(|s| {let mut s=s.borrow_mut(); s.active=s.index%64==0; s.index+=1;}); }
+        let guard = self::phase(if phase==RunPhase::Kernel {0} else {1});
+        let result=work(); drop(guard);
+        if phase==RunPhase::Encoder { STATE.with(|s| s.borrow_mut().active=false); }
+        result
+    }
+}
+pub fn json()->String {
+    STATE.with(|s| {let s=s.borrow(); format!("{{\"nanos\":{:?},\"hits\":{:?}}}",s.nanos,s.hits)})
+}
